from typing import List, Tuple

def max_product(nums: List[int]) -> Tuple[int, int]:
    if len(nums) < 2:
        raise ValueError("Array must contain at least two elements")

    max1, max2 = float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return (max1, max2) if max1 * max2 > min1 * min2 else (min1, min2)

# Test the function with the provided test case
assert max_product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)

import math

def next_Perfect_Square(n):
    if n < 0:
        return None
    root = math.isqrt(n)
    if root * root == n:
        return n
    return (root + 1) ** 2

def is_Isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    s_to_t = {}
    t_to_s = {}

    for char_s, char_t in zip(s, t):
        if char_s not in s_to_t and char_t not in t_to_s:
            s_to_t[char_s] = char_t
            t_to_s[char_t] = char_s
        elif s_to_t.get(char_s) != char_t or t_to_s.get(char_t) != char_s:
            return False

    return True

# Test the function with the provided test case
assert is_Isomorphic("paper", "title") == True

def remove_tuple(input_tuple):
    # Check if the input is a tuple
    if not isinstance(input_tuple, tuple):
        raise ValueError("Input must be a tuple")

    # If the input is empty, return an empty tuple
    if len(input_tuple) == 0:
        return ()

    # If the input has only one element, return that element as a tuple
    if len(input_tuple) == 1:
        return input_tuple

    # Convert the tuple to a set to remove duplicates
    unique_elements = set(input_tuple)

    # Convert the set back to a tuple
    result_tuple = tuple(unique_elements)

    return result_tuple
